/** A drone or artificer record, its pinned native tree, its templates and (artificers) the link projectile. */
export function artilleryChargerNative(r,n){
 const spec=SPECS[r?.prefabKey];
 if(!spec||r.key!==r.prefabKey||r.level!==0||!same(r.talents,spec.talents)||!same(r.skills,spec.skills)||!same(r.sp??null,spec.sp))return false;
 return same(closure(n),spec.components)&&Object.entries(spec.templates).every(([k,v])=>same(n.$template(k),v))
  &&Object.entries(spec.projectiles).every(([k,v])=>same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v));
}
export const droneChargeParams=r=>({sp:r.talents.bb["charge.sp"]});
export const artificerChargeParams=r=>{const s=r.skills[0];return {maxSp:r.sp.maxSp,initSp:r.sp.initSp,increment:r.sp.increment,preDelay:f32(0.6669999957084656),
 link:20,interval:1,sp:s.bb.sp,penalty:s.bb["enemy_dmech_charge[sp_reduce].sp"],postDelay:f32(0.6669999957084656)};};
